CREATE TABLE users (user_id INTEGER NOT NULL, name VARCHAR(50) NOT NULL, country CHAR(2) NOT NULL, signup DATE NOT NULL, premium BOOLEAN NOT NULL, score REAL NOT NULL);
CREATE TABLE events (id BIGINT NOT NULL, user_id INTEGER NOT NULL, ts TIMESTAMP NOT NULL, amount DOUBLE NOT NULL, ok BOOLEAN NOT NULL, kind VARCHAR(20) NOT NULL, note VARCHAR(100));
CREATE TABLE prices (sku VARCHAR(10) NOT NULL, price DECIMAL(10,4) NOT NULL, qty INTEGER NOT NULL);
